/* ═══ Cargador de módulos interno ═══
   Reemplaza a require('./store') sin necesidad de archivos sueltos. */
const __mods = {}, __defs = {};
function __definir(nombre, fn){ __defs[nombre] = fn; }
function __requerir(nombre){
  // Lo que no esté aquí dentro (express, pg, fs...) va al require real
  if (!__defs[nombre]) return require(nombre);
  if (__mods[nombre]) return __mods[nombre];
  const module = { exports: {} };
  __mods[nombre] = module.exports;
  __defs[nombre](module, module.exports, __requerir);
  __mods[nombre] = module.exports;
  return module.exports;
}

